package com.yeyamo_mobile.api.referral_service.infrastructure.messaging;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.referral_service.application.ReferralApplicationService;
class ReferralEventConsumerTest{@Test void consumesUserCreatedOnlyOnce()throws Exception{var service=mock(ReferralApplicationService.class);var processed=mock(ProcessedEventRepository.class);when(processed.existsById(any())).thenReturn(false,true);var consumer=new ReferralEventConsumer(new ObjectMapper(),service,processed);String raw="{\"eventId\":\"11111111-1111-1111-1111-111111111111\",\"eventType\":\"user.created\",\"eventVersion\":1,\"payload\":{\"userId\":\"u1\",\"email\":\"a@example.com\"}}";consumer.consume(raw);consumer.consume(raw);verify(service).onUserCreated(any(),eq("u1"),eq("a@example.com"),isNull());verify(processed).save(any());}@Test void consumesMissionCompletion()throws Exception{var service=mock(ReferralApplicationService.class);var processed=mock(ProcessedEventRepository.class);var consumer=new ReferralEventConsumer(new ObjectMapper(),service,processed);consumer.consume("{\"eventId\":\"22222222-2222-2222-2222-222222222222\",\"eventType\":\"mission.completed\",\"eventVersion\":1,\"payload\":{\"userId\":\"u2\"}}");verify(service).onMissionCompleted(any(),eq("u2"),isNull());}}
